let progress:DayProgress[]=Array.from({length:6},()=>({completed:false}));
let star:StarInput={...defaultStar};let worldRevision=0;let user:User|null=null;let saveTimer:number|undefined;let syncMessage='Saved on this device';
try{const raw=localStorage.getItem(progressKey);if(raw){const parsed=JSON.parse(raw);if(Array.isArray(parsed)&&parsed.length===6)progress=parsed.map(p=>({completed:p.completed===true&&typeof p.solverVersion==='string',validatedAt:p.validatedAt,solverVersion:p.solverVersion}));}}catch{}
// A completion record is only valid when written by a future trusted challenge validator.
// Current tutorial calculators DO NOT complete a day.
const isUnlocked=(i:number)=>i===0||progress.slice(0,i).every(p=>p.completed&&p.solverVersion===GRAPH_SOLVER);
function persistWorld(){clearTimeout(saveTimer);saveTimer=window.setTimeout(async()=>{try{const graphs:SavedWorld['graphs']={};for(let i=0;i<6;i++){const raw=localStorage.getItem('before-adam-v06-'+i);if(raw){try{graphs[String(i)]=JSON.parse(raw)}catch{}}}const current=graphs['0'] as {nodes:Node[];edges:Edge[]}|undefined;const checked=current?checkStarGraph(current.nodes,current.edges):null;const world:SavedWorld={schemaVersion:2,revision:++worldRevision,updatedAt:Date.now(),graphs,star,day1Evidence:checked?.complete?{solverVersion:GRAPH_SOLVER,signature:JSON.stringify(current),completedAt:Date.now()}:undefined};await writeLocal(world);syncMessage='Saved on this device';}catch(e){console.warn('Local save failed',e);syncMessage='Local save failed'}} ,180)}
async function restoreWorld(){try{const world=await readLocal();if(world){star={...defaultStar,...world.star};worldRevision=world.revision;for(const [key,value] of Object.entries(world.graphs||{}))if(/^[0-5]$/.test(key))localStorage.setItem('before-adam-v06-'+key,JSON.stringify(value));const g=world.graphs?.['0'] as {nodes:Node[];edges:Edge[]}|undefined;const verified=g?checkStarGraph(g.nodes,g.edges):null;progress[0]=world.day1Evidence?.solverVersion===GRAPH_SOLVER&&world.day1Evidence.signature===JSON.stringify(g)&&verified?.complete?{completed:true,validatedAt:new Date(world.day1Evidence.completedAt).toISOString(),solverVersion:GRAPH_SOLVER}:{completed:false};localStorage.setItem(progressKey,JSON.stringify(progress));}}catch(e){console.warn('IndexedDB unavailable; keeping browser graph saves',e)} }
async function syncCloud(direction:'upload'|'download'){if(!user)return alert('Sign in first');try{if(direction==='upload'){const world=await readLocal();if(!world)return alert('No local save yet');const remote=await readCloud(user.uid);if(remote&&remote.updatedAt>world.updatedAt&&!confirm('The cloud save is newer. Overwrite it with this device?'))return;await writeCloud(user.uid,world);syncMessage='Cloud saved';}else{const remote=await readCloud(user.uid);if(!remote)return alert('No cloud save found');if(!confirm('Replace this device’s current world with the cloud save?'))return;await writeLocal(remote);await restoreWorld();syncMessage='Cloud save restored';}render()}catch(e){alert('Cloud sync failed: '+String(e))}}
function authControls(){const el=document.querySelector<HTMLElement>('#account-controls');if(!el)return;el.innerHTML=user?`<span class="account-name">${esc(user.displayName||user.email||'Signed in')}</span><button id="cloud-upload">☁ Save cloud</button><button id="cloud-download">↓ Restore cloud</button><button id="signout">Sign out</button>`:`<button id="google-login" ${cloudConfigured?'':'disabled title="Firebase setup required"'}>Google login</button><button id="github-login" ${cloudConfigured?'':'disabled title="Firebase setup required"'}>GitHub login</button>`;el.querySelector<HTMLButtonElement>('#google-login')?.addEventListener('click',()=>login('google').catch(e=>alert(String(e))));el.querySelector<HTMLButtonElement>('#github-login')?.addEventListener('click',()=>login('github').catch(e=>alert(String(e))));el.querySelector<HTMLButtonElement>('#signout')?.addEventListener('click',()=>logout().catch(e=>alert(String(e))));el.querySelector<HTMLButtonElement>('#cloud-upload')?.addEventListener('click',()=>syncCloud('upload'));el.querySelector<HTMLButtonElement>('#cloud-download')?.addEventListener('click',()=>syncCloud('download'));}

