function openMission(index:number){
 if(index<0||index>=missionItems().length)return;
 if(challengeWorkspace){closeMission(false);}
 selectedMissionChallenge=index;pending=null;selected=null;tab='nodes';
 if(day===0){masterWorkspace={nodes:clone(nodes),edges:clone(edges)};const part=extractChallengeGraph(day,index,masterWorkspace);nodes=part.nodes;edges=part.edges;focusedChallenge=null;guideIndex=Math.min(index,guideSteps.length-1);challengeWorkspace=true;}
 else{masterWorkspace={nodes:clone(nodes),edges:clone(edges)};const id=missionItems()[index].id;const stored=loadChallengeGraph(localStorage,day,id);const graph=stored||starterGraph(day);nodes=clone(graph.nodes);edges=clone(graph.edges);challengeWorkspace=true;}
 graphScrollX=0;graphScrollY=0;render();
}
function closeMission(show=true){if(!challengeWorkspace)return;
 const id=missionItems()[selectedMissionChallenge]?.id;
 if(id)saveChallengeGraph(localStorage,day,id,{nodes,edges});
 if(masterWorkspace){
  if(day===0){const merged=mergeChallengeGraph(day,selectedMissionChallenge,masterWorkspace,{nodes,edges});nodes=merged.nodes;edges=merged.edges;}
  else{nodes=masterWorkspace.nodes;edges=masterWorkspace.edges;}
  masterWorkspace=null;
 }
 challengeWorkspace=false;focusedChallenge=null;pending=null;selected=null;tab='challenges';
 if(day===0)save();
 if(show)render();
}

function missionItems(){return challengeDefinitions(day);}
function renderChallengeSaved(){syncMessage='Challenge saved on this device';}
function missionPicker(){const items=missionItems();const status=evaluateDayGraphs(day,masterWorkspace||{nodes,edges});return `<div class="mission-picker"><strong>Day ${day+1} · Maths challenges</strong><p>Choose a challenge to work on. Each feeds into the day’s final simulation as its physics model becomes available.</p><div class="mission-picker-list">${items.map((c,i)=>`<button type="button" data-mission-index="${i}" aria-pressed="${selectedMissionChallenge===i}">${i+1}. ${esc(c.title)} · ${status.challenges[i]?.state==='passed'?'✓ Passed':status.challenges[i]?.state==='planned'?'Planned':'To solve'}</button>`).join('')}</div>${challengeWorkspace?`<button type="button" id="close-mission">← Back to day overview</button><p class="mission-note">Challenge graph saves separately. The master simulation only receives validated results.</p>`:''}${day>0?`<p class="mission-note">Challenge ${selectedMissionChallenge+1} of ${items.length}: ${esc(items[selectedMissionChallenge]?.title||'')}. Full challenge physics is still planned; the existing starter node graph remains available below. Completing the starter does not complete the day.</p>`:''}</div>`;}

function challengesView(){const status=evaluateDayGraphs(day,masterWorkspace||{nodes,edges});const items=missionItems();const master=masterWorkspace||{nodes,edges};const checked=day===0?checkStarGraph(master.nodes,master.edges):null;return `<div class="challenges-view"><h2>Day ${day+1} · Challenges</h2><p>Choose a challenge to open its graph, learn the maths and connect its output to the master simulation.</p>${items.map((item,i)=>{const state=status.challenges[i]?.state||'planned';const formula=day===0?guideSteps[i]:null;const wired=formula?formula.inputs.every((p,slot)=>master.edges.some(e=>e.from===p.id&&e.to===formula.id&&e.slot===slot)):false;return `<article class="challenge-entry"><div><strong>${i+1}. ${esc(item.title)}</strong><small>${day===0?(wired?'✓ Formula inputs connected':'○ Formula graph incomplete'):(state==='passed'?'✓ Validated':state==='planned'?'○ Physics model planned':'○ To solve')}</small>${formula?`<p><code>${esc(formula.formula)}</code></p><p>${esc(formula.explanation)}</p>`:''}</div><button data-mission-index="${i}">Open graph →</button></article>`}).join('')}${checked?`<p class="challenge-summary">${checked.complete?'✓ Star validated and connected':'Graph not yet complete — individual physics checks do not mean the star is finished.'}</p><button id="master-graph" type="button">Open master graph · connect final output →</button>`:''}</div>`;}
function starDetailsView(){if(day!==0)return '<div class="star-details"><p>Stellar measurements are available on Day 1.</p></div>';const source=masterWorkspace||{nodes,edges};const check=checkStarGraph(source.nodes,source.edges);const p=check.input;const ready=check.complete;const rows:[string,string,string][]=[['Radius',p?`${format(p.radius)} R☉ · ${format(p.radius*695700)} km`:'—','Solar radius'],['Diameter',p?`${format(p.radius*2)} R☉ · ${format(p.radius*1391400)} km`:'—','Twice the radius'],['Mass',p?`${format(p.mass)} M☉ · ${(p.mass*1.98847e30).toExponential(3)} kg`:'—','Solar mass'],['Surface temperature',p?`${format(5772*Math.pow(Math.max(.001,p.luminosity)/(Math.max(.001,p.radius)**2),.25))} K`:'—','Stefan–Boltzmann estimate'],['Core temperature',p?`${format(p.coreMK)} MK`:'—','Model input'],['Luminosity',p?`${format(p.luminosity)} L☉ · ${(p.luminosity*3.828e26).toExponential(3)} W`:'—','Model input'],['Surface gravity',p?`${format(274*p.mass/(p.radius*p.radius))} m/s²`:'—','Newtonian estimate'],['Stability',ready?'✓ Stable':p?'Not yet validated':'Missing inputs','Requires a complete connected graph']];return `<div class="star-details"><h2>★ Star details</h2><p>${ready?'Validated stellar model':'Preview values only — connect and validate the master graph to confirm stability.'}</p><div class="star-detail-grid">${rows.map(([label,value,info])=>`<div class="star-detail"><small>${label}</small><strong>${value}</strong><span>${info}</span></div>`).join('')}</div><p class="mission-note">Educational one-zone approximations; magnetic sunspots and flares are illustrative rather than predicted by the five stellar input parameters.</p></div>`;}
function setupChallengeList(){document.querySelectorAll<HTMLButtonElement>('[data-mission-index]').forEach(b=>b.onclick=()=>{openMission(Number(b.dataset.missionIndex));setView('nodes')});document.querySelector<HTMLButtonElement>('#master-graph')?.addEventListener('click',()=>{if(challengeWorkspace)closeMission(false);focusedChallenge=null;tab='nodes';setView('nodes')});}
function focusIds(){if(day!==0||parentGraph||!focusedChallenge)return null;const step=guideSteps.find(s=>s.id===focusedChallenge);return step?new Set([step.id,...step.inputs.map(x=>x.id)]):null;}
function focusChallenge(id:string|null){focusedChallenge=id;pending=null;selected=null;tab='nodes';graphScrollX=0;graphScrollY=0;render();}
let hasStarted=false;
let installPrompt:Event|null=null;
let updateWorker:ServiceWorker|null=null;
const landing=()=>{app.innerHTML=`<div class="landing"><div class="landing-card"><img src="${import.meta.env.BASE_URL}icons/creation.svg" width="108" height="108" alt="Creation logo"/><div class="landing-kicker">GOD'S MATHEMATICS</div><h1>BEFORE ADAM</h1><p>Create a star. Shape a planet. Build a living world through mathematics.</p><p class="landing-note">Six days · 65 planned challenges · Learn by experimenting</p><div class="level-chooser" role="group" aria-label="Choose learning level"><button data-level="2" aria-pressed="${learningLevel===2}">Level 2 · GCSE</button><button data-level="3" aria-pressed="${learningLevel===3}">Level 3 · A Level</button></div><p class="landing-note">Level 2 includes guided steps. Level 3 adds equation editing and independent exploration. Both use the same educational physics models.</p><div id="account-controls" class="account-controls"></div><button id="landing-tutorial">▶ Guided demo</button><button id="start-game">▶ Begin Creation</button><button id="install-game" hidden>⬇ Install app</button><p class="landing-note">Guest play saves your graphs in this browser. Cloud sign-in requires Firebase configuration. Guest progress is stored locally.</p><div class="landing-version">Version ${APP_VERSION}</div></div></div>`;document.querySelectorAll<HTMLButtonElement>('[data-level]').forEach(b=>b.onclick=()=>{learningLevel=Number(b.dataset.level) as LearningLevel;localStorage.setItem('creation-learning-level',String(learningLevel));landing()});document.querySelector<HTMLButtonElement>('#landing-tutorial')!.onclick=()=>{hasStarted=true;load(0,true);tutorialStep=0;render()};document.querySelector<HTMLButtonElement>('#start-game')!.onclick=()=>{hasStarted=true;load(0)};updateInstallButton();authControls();};
function updateInstallButton(){const b=document.querySelector<HTMLButtonElement>('#install-game');if(b){b.hidden=!installPrompt;b.onclick=async()=>{if(!installPrompt)return;const e=installPrompt as Event&{prompt:()=>Promise<void>};await e.prompt();installPrompt=null;updateInstallButton();};}}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;updateInstallButton()});
function showUpdate(){if(document.querySelector('#app-update'))return;const overlay=document.createElement('div');overlay.id='app-update';overlay.className='update-overlay';overlay.innerHTML='<section role="dialog" aria-modal="true" aria-labelledby="update-title" class="update-dialog"><h2 id="update-title">App has been updated</h2><p>A newer version of Creation Studio is ready. Save your work and update now, or continue playing.</p><button id="apply-update">Update now</button><button id="later-update">Later</button></section>';document.body.append(overlay);overlay.querySelector<HTMLButtonElement>('#later-update')!.onclick=()=>overlay.remove();overlay.querySelector<HTMLButtonElement>('#apply-update')!.onclick=()=>{save();if(updateWorker)updateWorker.postMessage({type:'SKIP_WAITING'});else location.reload();};}
async function registerPwa(){if(!('serviceWorker'in navigator)||!import.meta.env.PROD)return;let refreshing=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(refreshing)return;refreshing=true;location.reload()});try{const registration=await navigator.serviceWorker.register(import.meta.env.BASE_URL+'sw.js',{scope:import.meta.env.BASE_URL});if(registration.waiting&&navigator.serviceWorker.controller){updateWorker=registration.waiting;showUpdate();}registration.addEventListener('updatefound',()=>{const worker=registration.installing;if(!worker)return;worker.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller){updateWorker=worker;showUpdate();}})});}catch(err){console.warn('Offline installation unavailable',err)}}

const orbital=new OrbitalLab();let orbitFocus='Earth';let orbitScale:'inner'|'outer'='outer';
let graphScrollX=0,graphScrollY=0;
let splitPercent=Math.min(80,Math.max(20,Number(localStorage.getItem('creation-split-percent')||50)));
let inspectorHelp=false;
let inspectorTab:'learn'|'edit'|'output'='learn';
let inspectorOpen=false;
type LearningLevel=2|3;
let learningLevel:LearningLevel=localStorage.getItem('creation-learning-level')==='3'?3:2;
let tutorialStep=-1;
let parentGraph:{nodes:Node[];edges:Edge[];groupId:string}|null=null;
let bodies:Body[]=[],trails:Record<string,{x:number;y:number}[]>={},simTime=0,baseEnergy=0,simKey='';
let day=0,tab:'nodes'|'maths'|'parameters'|'orbits'|'challenges'|'details'='challenges',nodes:Node[]=[],edges:Edge[]=[],pending:string|null=null,selected:string|null=null,subgraph=false,playing=true,t=0,zoom=1;
const store='before-adam-v06'; // Retain saved graphs across versions
const clone=<T,>(x:T):T=>JSON.parse(JSON.stringify(x));
function load(i:number,sandbox=false){if(!sandbox&&!isUnlocked(i)){alert('Complete all challenges and the stability test in the previous day to unlock this day.');return;}parentGraph=null;masterWorkspace=null;challengeWorkspace=false;simKey='';day=i;focusedChallenge=i===0?'gravity':null;selectedMissionChallenge=0;exploring=sandbox&&!isUnlocked(i);const saved=localStorage.getItem(store+'-'+i);let v=saved?JSON.parse(saved):stages[i];if(i===0&&!v.nodes?.some((n:Node)=>n.op==='star-fusion')){if(saved)localStorage.setItem(store+'-0-legacy',saved);v=newStarGraph();localStorage.setItem(store+'-0',JSON.stringify(v));}nodes=clone(v.nodes);edges=clone(v.edges);if(i===0){updateDay1Progress();guideIndex=nextGuideStep(edges);connectionNotice='Select an output socket, then the highlighted formula input.';}pending=null;selected=null;subgraph=false;refreshChallengeEvidence();render();}
function currentWorldGraphs(){const graphs:Partial<Record<number,Graph>>={};for(let i=0;i<6;i++){try{const raw=localStorage.getItem(store+'-'+i);if(raw)graphs[i+1]=JSON.parse(raw) as Graph}catch{}}graphs[day+1]=masterWorkspace|| (parentGraph?{nodes:parentGraph.nodes,edges:parentGraph.edges}:{nodes,edges});return graphs}
function refreshChallengeEvidence(){const g=parentGraph?{nodes:parentGraph.nodes,edges:parentGraph.edges}:{nodes,edges};challengeLedger=reconcile(challengeLedger,day+1,learningLevel,g,deriveWorld(currentWorldGraphs()));writeLedger(challengeLedger)}
function save(){if(challengeWorkspace){const id=missionItems()[selectedMissionChallenge]?.id;if(id)saveChallengeGraph(localStorage,day,id,{nodes,edges});renderChallengeSaved();return;}if(day===0){missionItems().forEach((item,i)=>saveChallengeGraph(localStorage,day,item.id,extractChallengeGraph(day,i,{nodes,edges})));}refreshChallengeEvidence();if(parentGraph){const g=parentGraph.nodes.find(n=>n.id===parentGraph!.groupId);if(g)g.group={nodes:clone(nodes),edges:clone(edges)};localStorage.setItem(store+'-'+day,JSON.stringify({nodes:parentGraph.nodes,edges:parentGraph.edges}));}else localStorage.setItem(store+'-'+day,JSON.stringify({nodes,edges}));if(day===0)updateDay1Progress();persistWorld();}
const esc=(s:string)=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
function updateDay1Progress(){const g=day===0?{nodes:parentGraph?parentGraph.nodes:nodes,edges:parentGraph?parentGraph.edges:edges}:JSON.parse(localStorage.getItem(store+'-0')||'null');const ok=g?evaluateDayGraphs(0,g).complete:false;progress[0]=ok?{completed:true,solverVersion:GRAPH_SOLVER,validatedAt:new Date().toISOString()}:{completed:false};localStorage.setItem(progressKey,JSON.stringify(progress));}
function applyDemo(preset:DemoPreset){if(day!==0)return;if(!confirm('Load the '+preset+' example? This replaces the current Day 1 graph. Your current work will be saved as a backup.'))return;try{localStorage.setItem(store+'-0-before-demo',JSON.stringify({nodes,edges}))}catch{}parentGraph=null;const g=makeDay1Demo(preset);nodes=g.nodes;edges=g.edges;guideIndex=nextGuideStep(edges);connectionNotice=describeDay1Demo(preset);save();tab='nodes';render()}
function restoreDemoBackup(){const backup=localStorage.getItem(store+'-0-before-demo');if(!backup)return alert('No previous graph backup found.');if(!confirm('Restore the graph from before you loaded a demo?'))return;try{const g=JSON.parse(backup) as {nodes:Node[];edges:Edge[]};parentGraph=null;nodes=g.nodes;edges=g.edges;save();render()}catch{alert('The backup could not be read.')}}
function applyLab(mode:Preset){if(day===0)return;if(!confirm('Load '+mode+' example and back up your graph?'))return;localStorage.setItem(store+'-'+day+'-backup',JSON.stringify({nodes,edges}));const g=labPreset(day,stages[day],mode);nodes=g.nodes;edges=g.edges;parentGraph=null;save();tab='nodes';render()}
function restoreLab(){const raw=localStorage.getItem(store+'-'+day+'-backup');if(!raw)return alert('No graph backup');const g=JSON.parse(raw);nodes=g.nodes;edges=g.edges;parentGraph=null;save();render()}
function addNode(op:string){const id='n'+Date.now();const kind=op==='constant'?'number':op==='group'?'group':'formula';const group=op==='group'?defaultGroup():undefined;nodes.push({id,kind,op,label:op==='constant'?'Number':op==='group'?'Custom formula group':symbols[op]||op,x:90+Math.random()*220,y:100+Math.random()*180,value:1,group});selected=id;save();render();}
function setupSplitDivider(){const grip=document.querySelector<HTMLElement>('#split-divider'),main=document.querySelector<HTMLElement>('main');if(!grip||!main)return;const update=(p:number)=>{splitPercent=Math.max(20,Math.min(80,Math.round(p)));main.style.setProperty('--split-percent',splitPercent+'%');grip.setAttribute('aria-valuenow',String(splitPercent));world3d?.resize()};grip.onkeydown=e=>{if(e.key==='ArrowUp'||e.key==='ArrowDown'){e.preventDefault();update(splitPercent+(e.key==='ArrowUp'?-5:5));localStorage.setItem('creation-split-percent',String(splitPercent))}else if(e.key==='Home'){update(20)}else if(e.key==='End'){update(80)}};grip.onpointerdown=e=>{if(viewMode!=='split')return;e.preventDefault();grip.setPointerCapture(e.pointerId);const move=(ev:PointerEvent)=>{const rect=main.getBoundingClientRect();update((ev.clientY-rect.top)/rect.height*100)};const end=()=>{grip.removeEventListener('pointermove',move);grip.removeEventListener('pointerup',end);grip.removeEventListener('pointercancel',end);localStorage.setItem('creation-split-percent',String(splitPercent))};grip.addEventListener('pointermove',move);grip.addEventListener('pointerup',end);grip.addEventListener('pointercancel',end)}}
function equationInspector(n:Node){const editable=n.op==='expression'||['add','multiply','divide','sqrt'].includes(n.op);return `<div class="equation-inspector"><strong>Equation editor</strong><p>Formula: ${esc(n.op==='expression'?(n.expression||'A+B'):(symbols[n.op]||n.op))}</p><p>${learningLevel===2?'GCSE: start with the original formula and experiment with input values.':'A Level: write a custom expression using A and B, e.g. A*B/2 or (A+B)^2.'}</p><form id="equation-editor"><label>Custom equation (A and B) <input id="equation-input" value="${esc(n.expression||'A+B')}" placeholder="A+B" /></label><button type="submit">Apply custom equation</button></form><button id="equation-reset" ${stages[day].nodes.some(x=>x.id===n.id)?'':'disabled'}>Restore original formula</button><small>Original physics formulas are fixed; applying a custom expression switches this node to a generic mathematical calculation. It will no longer count as the original Day 1 physics formula.</small></div>`}
let nodeLibrary:NodeLibrary|null=null;
function nodeLessonMarkup(n:Node){const lesson=resolveNodeLesson(nodeLibrary,day,n);if(!lesson)return '<h3>How it works</h3><p>'+esc(nodeExplanation(n))+'</p><p class="node-modal-tip">Detailed lesson is not available for this node yet.</p>';return '<h3>'+esc(lesson.title)+'</h3><h4>What does it mean?</h4><p>'+esc(lesson.meaning)+'</p><h4>Units</h4><p>'+esc(lesson.unit)+'</p><h4>Real-world examples</h4><ul class="node-lesson-examples">'+lesson.examples.map(ex=>'<li><strong>'+esc(ex.name)+' — '+esc(ex.value)+'</strong><p>'+esc(ex.explanation)+'</p></li>').join('')+'</ul><h4>Try it in the simulation</h4><p>'+esc(lesson.experiment)+'</p><h4>Model limitations</h4><p>'+esc(lesson.modelLimitations)+'</p>'}
function nodeUnitField(n:Node){const options=UNIT_CHOICES[n.unit||''];if(!options)return '<label>Unit<input name="unit" value="'+esc(n.unit||'')+'" readonly /></label>';return '<label>Unit<select name="unit" id="node-unit-select">'+options.map((option,i)=>'<option value="'+esc(option.unit)+'" '+(i===0?'selected':'')+'>'+esc(option.label)+'</option>').join('')+'</select></label>'}
function nodeModalMarkup(){const n=nodes.find(x=>x.id===selected);if(!n)return '';const inputs=edges.filter(e=>e.to===n.id).map(e=>nodes.find(x=>x.id===e.from)?.label||e.from);const formula=n.kind==='formula'||n.kind==='group';return `<div class="node-modal-backdrop" id="node-modal-backdrop"><section class="node-modal" role="dialog" aria-modal="true" aria-labelledby="node-modal-heading"><div class="node-modal-heading"><h2 id="node-modal-heading">${esc(n.label)}</h2><button type="button" id="node-modal-close" aria-label="Close node editor">✕</button></div><div class="node-modal-tabs"><button type="button" id="node-modal-info" aria-pressed="${inspectorHelp}">ⓘ Learn about this node</button><button type="button" id="node-modal-edit" aria-pressed="${inspectorTab==='edit'}">⚙ Edit parameters</button><button type="button" id="node-modal-output" aria-pressed="${inspectorTab==='output'}">◉ Output</button></div>${inspectorTab==='output'?`<div class="node-modal-info"><h3>Calculated output</h3><p class="output-preview">${esc(nodeOutputPreview(n.id).message)}</p><h4>Required input connections</h4>${day===0&&guideSteps.some(s=>s.id===n.id)?`<ul>${guideSteps.find(s=>s.id===n.id)!.inputs.map((input,i)=>`<li>Input ${i+1}: ${esc(nodes.find(x=>x.id===input.id)?.label||input.id)} (${esc(input.unit)})</li>`).join('')}</ul>`:`<p>Connect the input sockets on the graph to calculate this node.</p>`}</div>`:inspectorTab==='learn'?`<div class="node-modal-info">${nodeLessonMarkup(n)}<p><strong>Node type:</strong> ${esc(n.kind)} · <strong>Operation:</strong> ${esc(n.op)}</p>${formula?`<p><strong>Equation:</strong> ${esc(n.expression||symbols[n.op]||n.op)}</p>`:''}<p><strong>Inputs:</strong> ${inputs.length?esc(inputs.join(', ')):'No connected inputs yet'}</p><p><strong>Output unit:</strong> ${esc(n.unit||'not specified')}</p><button type="button" id="node-modal-edit-cta">Edit parameters →</button></div>`:`<form id="node-modal-form">${isBuiltInNode(n)?`<div class="fixed-node-label"><strong>Node name</strong><span>${esc(n.label)}</span><small>Built-in scientific nodes have fixed names.</small></div>`:`<label>Node label<input name="label" required maxlength="100" value="${esc(n.label)}" /></label>`}${n.kind==='number'?`<label>Numeric value<input name="value" type="number" step="any" required value="${n.value??0}" /></label>${nodeUnitField(n)}<p class="node-modal-tip">Adjust the value and press Apply. Changes update the connected simulation.</p>`:formula?isBuiltInNode(n)?`<div class="fixed-node-label"><strong>Fixed scientific equation</strong><span>${esc(symbols[n.op]||n.op)}</span><small>Inputs A and B are wired connections. Edit the connected input nodes, not this equation.</small></div>`:`<label>Operator<select name="operator">${[['add','Add (+)'],['multiply','Multiply (×)'],['divide','Divide (÷)'],['sqrt','Square root (√A)'],['expression','Custom expression']].map(([op,title])=>`<option value="${op}" ${n.op===op?'selected':''}>${title}</option>`).join('')}</select></label><p>A and B are fixed input sockets. Their values come from connected nodes.</p><label>Custom expression (only when Custom is selected)<input name="expression" value="${esc(n.expression||'A+B')}" /></label>`:`<p>This node has no numeric parameter. You can change its label and connected wires.</p>`}<div class="node-modal-actions"><button type="submit">Apply changes</button><button type="button" id="node-modal-cancel">Cancel</button></div></form>`}</section></div>`}
function setupNodeModal(){const close=()=>{inspectorOpen=false;render()};document.querySelector<HTMLButtonElement>('#node-modal-close')?.addEventListener('click',close);document.querySelector<HTMLButtonElement>('#node-modal-cancel')?.addEventListener('click',close);document.querySelector<HTMLElement>('#node-modal-backdrop')?.addEventListener('click',e=>{if(e.target===e.currentTarget)close()});document.querySelector<HTMLButtonElement>('#node-modal-info')?.addEventListener('click',()=>{inspectorHelp=true;inspectorTab='learn';render()});const edit=()=>{inspectorHelp=false;inspectorTab='edit';render()};document.querySelector<HTMLButtonElement>('#node-modal-edit')?.addEventListener('click',edit);document.querySelector<HTMLButtonElement>('#node-modal-output')?.addEventListener('click',()=>{inspectorTab='output';render()});document.querySelector<HTMLButtonElement>('#node-modal-edit-cta')?.addEventListener('click',edit);document.querySelector<HTMLSelectElement>('#node-unit-select')?.addEventListener('change',e=>{const n=nodes.find(x=>x.id===selected);const options=UNIT_CHOICES[n?.unit||''];const selectedOption=options?.find(x=>x.unit===(e.target as HTMLSelectElement).value);const input=document.querySelector<HTMLInputElement>('#node-modal-form [name="value"]');if(n&&selectedOption&&input)input.value=formatUnitValue(fromCanonical(n.value??0,selectedOption))});document.querySelector<HTMLFormElement>('#node-modal-form')?.addEventListener('submit',e=>{e.preventDefault();const n=nodes.find(x=>x.id===selected);if(!n)return;const form=e.currentTarget as HTMLFormElement;const data=new FormData(form);const label=isBuiltInNode(n)?n.label:String(data.get('label')||'').trim();if(!label)return;const val=String(data.get('value')??'');if(n.kind==='number'){const number=Number(val);if(!Number.isFinite(number)||val.trim()===''){alert('Enter a finite numeric value');return}const choices=UNIT_CHOICES[n.unit||''];const choice=choices?.find(option=>option.unit===String(data.get('unit')));n.value=choice?toCanonical(number,choice):number}else if((n.kind==='formula'||n.kind==='group')&&!isBuiltInNode(n)){const op=String(data.get('operator')||'');if(!['add','multiply','divide','sqrt','expression'].includes(op))return;if(op==='expression'){const expr=String(data.get('expression')||'').trim();try{evaluateExpression(expr,2,3);n.expression=expr}catch(err){alert(String(err));return}}else n.expression=undefined;n.op=op;n.unit=undefined;if(op==='sqrt')edges=edges.filter(e=>e.to!==n.id||e.slot===0)}n.label=label;inspectorOpen=false;save();render()})}
function nodeExplanation(n:Node){const guide=guideSteps.find(s=>s.id===n.id);if(guide)return guide.explanation+' Example: '+guide.example;const info:Record<string,string>={constant:'An input parameter. Change its numeric value to see the graph and 3D result update.',add:'Adds the two connected inputs. Both quantities must have compatible units.',multiply:'Multiplies connected inputs. The result units are multiplied.',divide:'Divides input A by input B. Input B must not be zero.',sqrt:'Takes the square root of input A. Negative inputs are invalid.',frequency:'Light frequency is the speed of light divided by wavelength.',phase:'Estimates the phase of water from temperature and pressure.',gravity:'Surface gravity depends on planet mass divided by radius squared.',orbit:'Circular orbital speed depends on star mass and orbital radius.',flux:'Received stellar energy decreases with distance squared.',population:'Logistic growth models a population approaching carrying capacity.',display:'Shows the final value calculated by the connected graph.',group:'A compound formula containing another editable node graph.'};return info[n.op]||'This formula combines its connected inputs to calculate a result. Connect all required sockets.'}
function tutorialMarkup(){const steps=[['Choose your level','Level 2 provides more guidance; Level 3 encourages independent exploration. Both use the same starter simulations.'],['Explore the 3D result','Drag the 3D view to rotate it, use the wheel or pinch to zoom, and use the split-screen handle to resize.'],['Connect the nodes','Choose a node OUT socket, then connect it to the correct input socket on another node.'],['Read and edit equations','Open Maths, select Jump to node or Edit equation. Custom expressions use A and B.'],['Try a solution','Use Working, Nearly or Broken in the test panel, then change values to see the result.'],['Save your work','Changes save locally. Export a graph as JSON or use optional cloud sync.']];const [title,body]=steps[Math.min(tutorialStep,steps.length-1)];return `<div class="tutorial-overlay"><section role="dialog" aria-modal="true" aria-label="Guided tutorial" class="tutorial-dialog"><small>Step ${tutorialStep+1} of ${steps.length} · Level ${learningLevel}</small><h2>${esc(title)}</h2><p>${esc(body)}</p><div class="tutorial-controls"><button id="tour-prev" ${tutorialStep===0?'disabled':''}>Back</button><button id="tour-next">${tutorialStep===steps.length-1?'Finish':'Next'}</button><button id="tour-close">Skip tour</button></div></section></div>`}
function setupHelpAndTour(){document.querySelector<HTMLButtonElement>('#show-help')?.addEventListener('click',()=>{const msg=learningLevel===2?'GCSE / Level 2: follow the guided examples, connect the formula nodes, and adjust parameters.':'A Level / Level 3: inspect the equations, change variables, and use the custom A/B equation editor to explore mathematical relationships.';alert(msg+'\\n\\nNodes: click ⓘ for an explanation and editor. Maths: Jump to node or Edit equation. Split: drag the divider. Explore/Test: load a working, near-working or broken model. These are educational simplified simulations.')});document.querySelector<HTMLButtonElement>('#restart-tour')?.addEventListener('click',()=>{tutorialStep=0;render()});document.querySelector<HTMLButtonElement>('#tour-close')?.addEventListener('click',()=>{tutorialStep=-1;render()});document.querySelector<HTMLButtonElement>('#tour-prev')?.addEventListener('click',()=>{tutorialStep=Math.max(0,tutorialStep-1);render()});document.querySelector<HTMLButtonElement>('#tour-next')?.addEventListener('click',()=>{tutorialStep=tutorialStep>=5?-1:tutorialStep+1;render()})}
function setView(next:ViewMode){viewMode=next;try{localStorage.setItem('creation-view',next)}catch{}render()}
function graphDiagnostic(ev:ReturnType<typeof evaluate>){const out=ev.result;if(day===0&&!parentGraph&&!challengeWorkspace){const check=checkStarGraph(masterWorkspace?.nodes||nodes,masterWorkspace?.edges||edges);const required:{from:string;to:string;slot:number}[]=[...STAR_FORMULAS.flatMap(f=>f.inputs.map((from,slot)=>({from,to:f.id,slot}))),{from:'stable',to:'out',slot:0}];const wrong=edges.find(e=>{const intended=required.find(r=>r.to===e.to&&r.slot===e.slot);return intended&&intended.from!==e.from});if(wrong)return {state:'incorrect' as const,message:'Wrong wire: '+(nodes.find(n=>n.id===wrong.from)?.label||wrong.from)+' → '+(nodes.find(n=>n.id===wrong.to)?.label||wrong.to)+'. This input expects '+(required.find(r=>r.to===wrong.to&&r.slot===wrong.slot)?.from||'?')+'.',node:wrong.to};const missing=required.find(r=>!edges.some(e=>e.from===r.from&&e.to===r.to&&e.slot===r.slot));if(missing)return {state:'incomplete' as const,message:'Next connection: '+missing.from+' OUT → '+missing.to+' input '+(missing.slot+1)+'. '+(ev.errors[0]||''),node:missing.to};if(out===undefined||ev.errors.length)return {state:'incorrect' as const,message:ev.errors[0]||'Check the graph for invalid inputs.',node:'out'};if(!check.complete)return {state:'incorrect' as const,message:'Star not yet stable: '+(check.checks.find(c=>!c.passed)?.detail||'Check required inputs, units, duplicate wires and all seven physics checks.'),node:'stable'};return {state:'ready' as const,message:'Stable star · all seven physics checks passed',node:'out'}}if(out===undefined)return {state:'incomplete' as const,message:ev.errors[0]||'Connect the formula to the output.',node:'out'};return {state:'ready' as const,message:unit(day,out),node:'out'}}
function render(){world3d?.dispose();world3d=null;const oldScroll=document.querySelector<HTMLElement>('.graph-scroll');if(oldScroll){graphScrollX=oldScroll.scrollLeft;graphScrollY=oldScroll.scrollTop;}if(!hasStarted){landing();return;}const st=stages[day],activeMaster=challengeWorkspace&&masterWorkspace?masterWorkspace:{nodes:parentGraph?parentGraph.nodes:nodes,edges:parentGraph?parentGraph.edges:edges},ev=evaluate(activeMaster.nodes,activeMaster.edges),out=ev.result,diagnostic=graphDiagnostic(ev);app.innerHTML=`<header><div class="brand"><span class="star">✦</span><div><strong>BEFORE ADAM</strong><small>CREATION STUDIO · VITE + TYPESCRIPT</small></div></div><div class="header-actions"><button id="show-help">? Help</button><span class="level-indicator">Level ${learningLevel} · ${learningLevel===2?'GCSE':'A Level'}</span><details class="app-settings"><summary>⚙ Settings</summary><div class="settings-menu"><button id="restart-tour">▶ Demo</button><button id="account-toggle">☁ Account</button><button id="export" title="Export graph">⇩ Export</button><button id="reset">↺ Reset</button><label class="effects-option"><input type="checkbox" id="solar-effects" ${solarEffects?'checked':''}/> Animated solar effects</label><details><summary>Explore / Test days</summary><div class="settings-days">${stages.map((_,i)=>`<button data-sandbox="${i}">Day ${i+1}</button>`).join('')}</div><small>Preview only · no full-day credit</small></details></div></details></div></header><div id="account-panel" class="account-panel" hidden><div id="account-controls" class="account-controls"></div><p class="account-note">${esc(syncMessage)} · ${cloudConfigured?'Firebase available':'Firebase not configured'}</p></div><nav class="days">${stages.map((s,i)=>`<button data-day="${i}" ${isUnlocked(i)?'':'disabled aria-label="Day '+(i+1)+' locked" title="Complete the previous day to unlock"'} class="${day===i?'active':''}">${isUnlocked(i)?i+1:'🔒'}<span>${s.title.split('· ')[1]}</span></button>`).join('')}</nav><div class="view-switcher" role="group" aria-label="Workspace view"><button data-view="split" aria-pressed="${viewMode==='split'}">Split</button><button data-view="result" aria-pressed="${viewMode==='result'}">Full result</button><button data-view="nodes" aria-pressed="${viewMode==='nodes'}">Full nodes</button></div><main class="view-${viewMode}" style="--split-percent:${splitPercent}%"><section class="universe"><div class="section-head"><div><span class="eyebrow">${esc(st.verse)}</span><h1>${esc(st.title)}</h1><p>${esc(st.mission)}</p></div><button id="play">${playing?'Ⅱ Pause':'▶ Play'}</button></div><canvas id="sky" aria-label="Interactive 3D world. Drag to orbit, pinch or scroll to zoom."></canvas><button id="camera-reset" class="camera-reset" aria-label="Reset 3D camera">⟳</button>${day===0?'':worldMetricsPanel()}${day===0?'':challengeScorePanel()}${day===0?'':labPanel(day)}<div class="result" role="status" aria-live="polite"><span>${challengeWorkspace&&day!==0?'MASTER DAY PREVIEW':diagnostic.state==='ready'?'LIVE RESULT':diagnostic.state==='incorrect'?'GRAPH NEEDS CORRECTION':'INCOMPLETE GRAPH'}</span><strong>${out===undefined?(diagnostic.state==='incorrect'?'Incorrect connections':'Awaiting connections'):format(out)}</strong><small>${esc(challengeWorkspace&&day!==0?'Challenge edits are saved independently. The day remains incomplete until its dedicated physics validators are implemented.':diagnostic.message)}</small>${diagnostic.state!=='ready'?`<button id="result-fix" type="button">Locate issue in nodes ↗</button>`:''}</div></section><div id="split-divider" class="split-divider" role="separator" aria-label="Resize 3D result and node editor" aria-orientation="horizontal" aria-valuemin="20" aria-valuemax="80" aria-valuenow="${splitPercent}" tabindex="0"><span class="divider-grip">⋮⋮⋮ Drag to resize ⋮⋮⋮</span></div><section class="workshop"><div class="tabs">${(day===3?['challenges','nodes','maths','details','parameters','orbits'] as const:['challenges','nodes','maths','details','parameters'] as const).map(x=>`<button data-tab="${x}" class="${tab===x?'active':''}">${x==='challenges'?'✓ Challenges':x==='details'?'★ Star details':x==='nodes'?'◉ Nodes':x==='maths'?'∑ Maths':x==='orbits'?'◎ Orbits':'⚙ Parameters'}</button>`).join('')}</div><div class="workspace">${tab==='challenges'?challengesView():tab==='details'?starDetailsView():tab==='nodes'?nodesView():tab==='maths'?mathsView(ev.values,ev.errors):tab==='orbits'?orbitsView():paramsView()}</div></section></main><footer><span>${parentGraph?'Editing inside a formula group · use Back to save':esc(st.goal)}</span><span>Tap output → input to connect · ${edges.length} wire(s)</span></footer>${tutorialStep>=0?tutorialMarkup():''}${inspectorOpen?nodeModalMarkup():''}`;
 setupSplitDivider();setupHelpAndTour();setupChallengePanel();setupChallengeList();setupNodeModal();document.querySelector<HTMLButtonElement>('#result-fix')?.addEventListener('click',()=>{tab='nodes';selected=diagnostic.node;inspectorHelp=true;render();document.querySelector<HTMLElement>('[data-node="'+selected+'"]')?.scrollIntoView({block:'nearest',inline:'nearest'})});
 document.querySelectorAll<HTMLButtonElement>('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view as ViewMode));
 document.querySelector<HTMLButtonElement>('#camera-reset')!.onclick=()=>world3d?.reset();
 document.querySelector<HTMLInputElement>('#solar-effects')?.addEventListener('change',e=>{solarEffects=(e.target as HTMLInputElement).checked;try{localStorage.setItem('creation-solar-effects',solarEffects?'on':'off')}catch{}world3d?.setEffects(solarEffects)});
 document.querySelector<HTMLButtonElement>('#account-toggle')!.onclick=()=>{const panel=document.querySelector<HTMLElement>('#account-panel')!;panel.hidden=!panel.hidden;authControls()};
 if(day===0)setupStarUI();else setupLab();
 document.querySelectorAll<HTMLButtonElement>('[data-explain]').forEach(b=>b.onclick=()=>{const [d,i]=b.dataset.explain!.split(':').map(Number);const c=creationChallenges[d].items[i];alert(c.name+'\\n\\nThis challenge requires a dedicated physics calculation, unit-aware nodes and a stability validator.\\n\\nPrerequisite: '+(c.dependsOn.length?'complete the preceding challenge':'none'));});
 document.querySelectorAll<HTMLButtonElement>('[data-day]').forEach(b=>b.onclick=()=>load(Number(b.dataset.day)));
 document.querySelectorAll<HTMLButtonElement>('[data-sandbox]').forEach(b=>b.onclick=()=>load(Number(b.dataset.sandbox),true));
 document.querySelectorAll<HTMLButtonElement>('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab as typeof tab;render()});
 document.querySelector<HTMLButtonElement>('#play')!.onclick=()=>{playing=!playing;render()};
 document.querySelector<HTMLButtonElement>('#reset')!.onclick=()=>{if(confirm('Reset this day’s graph?')){parentGraph=null;localStorage.removeItem(store+'-'+day);if(day===0){progress[0]={completed:false};localStorage.setItem(progressKey,JSON.stringify(progress))}load(day);save()}};
 document.querySelector<HTMLButtonElement>('#export')!.onclick=()=>{const blob=new Blob([JSON.stringify({day,nodes,edges},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`before-adam-day-${day+1}.json`;a.click();URL.revokeObjectURL(a.href)};
 if(tab==='nodes'){wireUI();const sc=document.querySelector<HTMLElement>('.graph-scroll');if(sc){sc.scrollLeft=graphScrollX;sc.scrollTop=graphScrollY;sc.onscroll=()=>{graphScrollX=sc.scrollLeft;graphScrollY=sc.scrollTop;};}}if(tab==='parameters')parameterUI();if(tab==='orbits')orbitsUI();if(tab==='maths')mathUI();drawWires();try{world3d=new World3D(document.querySelector<HTMLCanvasElement>('#sky')!);world3d.setEffects(solarEffects)}catch(error){console.warn('WebGL unavailable, using 2D result',error)}drawUniverse();
}

function starPanel(){const result=checkStarGraph(parentGraph?parentGraph.nodes:nodes,parentGraph?parentGraph.edges:edges);const step=guideSteps[guideIndex]||guideSteps[0];const wired=step.inputs.filter((p,slot)=>edges.some(e=>e.from===p.id&&e.to===step.id&&e.slot===slot)).length;return `<details class="creation-mission star-lab" open><summary>★ Day 1 Guided Creation · ${result.checks.filter(c=>c.passed).length}/7 validated</summary><div class="tutorial" aria-label="Day 1 guided mathematics"><div class="tutorial-top"><strong>Step ${guideIndex+1} of ${guideSteps.length}: ${esc(step.title)}</strong><span>${wired}/${step.inputs.length} connections</span></div><p><code>${esc(step.formula)}</code></p><p>${esc(step.explanation)}</p><p class="tutorial-example">Example: ${esc(step.example)}</p><ol class="tutorial-inputs">${step.inputs.map((p,slot)=>`<li class="${edges.some(e=>e.from===p.id&&e.to===step.id&&e.slot===slot)?'connected':''}">Input ${slot+1}: <b>${esc(p.id)}</b> <small>${esc(p.unit)}</small> ${edges.some(e=>e.from===p.id&&e.to===step.id&&e.slot===slot)?'✓':'○'}</li>`).join('')}</ol><p id="connection-feedback" role="status" aria-live="polite">${esc(connectionNotice||'Tap the source OUT socket, then the destination input socket.')}</p><div class="tutorial-actions"><button id="open-challenge" type="button">Solve this graph →</button><button id="guide-prev" ${guideIndex===0?'disabled':''}>← Previous</button><button id="guide-next" ${guideIndex===guideSteps.length-1?'disabled':''}>Next →</button><button id="guide-focus">Show in Nodes</button></div></div><details><summary>All seven physics challenges</summary><ol>${result.checks.map(c=>`<li><span class="challenge-status ${c.passed?'passed':'failed'}">${c.passed?'✓':'◇'}</span> ${esc(c.id)}: ${esc(c.detail)}</li>`).join('')}</ol></details><p class="mission-note">${result.complete?'✓ Star validated. Day 2 unlocked.':'Connect the equations, check their units and pass all seven physical tests.'}</p><div class="demo-tools"><strong>🧪 Fun / Test Mode</strong><p>Load a real graph solution to explore the 3D result. Near miss and unstable examples help you experiment with the physics.</p><button data-demo="working">✓ Working solution</button><button data-demo="nearly">◒ Nearly working</button><button data-demo="broken">⚠ Unstable example</button><button id="demo-backup">↶ Restore my graph</button></div><button id="star-template">Restore unwired Day 1 nodes</button></details>`}
function setupStarUI(){document.querySelector<HTMLButtonElement>('#open-challenge')?.addEventListener('click',()=>{focusChallenge(guideSteps[guideIndex].id);setView('nodes')});document.querySelectorAll<HTMLButtonElement>('[data-demo]').forEach(b=>b.onclick=()=>applyDemo(b.dataset.demo as DemoPreset));document.querySelector<HTMLButtonElement>('#demo-backup')?.addEventListener('click',restoreDemoBackup);document.querySelector<HTMLButtonElement>('#guide-prev')?.addEventListener('click',()=>{guideIndex=Math.max(0,guideIndex-1);focusedChallenge=guideSteps[guideIndex].id;render()});document.querySelector<HTMLButtonElement>('#guide-next')?.addEventListener('click',()=>{guideIndex=Math.min(guideSteps.length-1,guideIndex+1);focusedChallenge=guideSteps[guideIndex].id;render()});document.querySelector<HTMLButtonElement>('#guide-focus')?.addEventListener('click',()=>{tab='nodes';focusedChallenge=guideSteps[guideIndex].id;selected=guideSteps[guideIndex].id;render();const target=document.querySelector<HTMLElement>('[data-node="'+selected+'"]');target?.scrollIntoView({block:'nearest',inline:'nearest',behavior:'smooth'})});document.querySelector<HTMLButtonElement>('#star-template')?.addEventListener('click',()=>{if(!confirm('Replace the current Day 1 graph with a new unwired template?'))return;parentGraph=null;const fresh=newStarGraph();nodes=fresh.nodes;edges=fresh.edges;save();render()});}
function labPanel(index:number){const spec=labSpec(index);if(!spec)return '';const r=labCheck(index,nodes,edges);return `<details class="creation-mission lab-panel" open><summary>🧪 Day ${index+1} · Tutorial / Test / Function</summary><p><strong>${esc(spec.title)}</strong> · ${esc(spec.concept)}</p><p><code>${esc(spec.formula)}</code></p><p>Goal: ${esc(spec.target)} · Result: ${r.value===undefined?'Not connected':format(r.value)} · ${r.passed?'✓ Starter passes':'◇ Needs work'}</p><p>${esc(r.reason)}</p><div class="lab-actions"><button data-lab="working">✓ Working</button><button data-lab="nearly">◒ Nearly</button><button data-lab="broken">⚠ Broken</button><button id="lab-restore">Restore graph</button><button id="lab-edit">Edit nodes</button></div><small>${exploring?'Sandbox preview. ':''}Starter model only: full-day challenge validators remain to be built.</small></details>`}
function setupLab(){document.querySelectorAll<HTMLButtonElement>('[data-lab]').forEach(b=>b.onclick=()=>applyLab(b.dataset.lab as Preset));document.querySelector<HTMLButtonElement>('#lab-restore')?.addEventListener('click',restoreLab);document.querySelector<HTMLButtonElement>('#lab-edit')?.addEventListener('click',()=>{tab='nodes';render()})}
function worldMetricsPanel(){const m=deriveWorld(currentWorldGraphs());const q=worldScore(m);const score=scoreAttempt(q);const raw=nodes.find(n=>n.id==='capacity')?.value||1000;return `<details class="world-metrics"><summary>🌍 Coupled world · quality ${score}/100</summary><p>Solar flux ${format(m.stellarFlux)} W/m² · climate ${format(m.surfaceC)} °C · gravity ${format(m.surfaceGravity)} m/s²</p><p>Liquid-water suitability ${format(m.liquidWaterSuitability*100)}% · photosynthesis ${format(m.photosynthesisPotential*100)}% · carrying-capacity factor ${format(m.carryingCapacityFactor*100)}%</p>${day===5?`<p>Climate-adjusted population capacity: ${format(effectivePopulationCapacity(raw,m))} organisms (compared with nominal ${format(raw)}).</p>`:''}<p>Feasibility ${format(q.feasibility)} · stability ${format(q.stability)} · efficiency ${format(q.efficiency)} · resilience ${format(q.resilience)}</p><small>Approximate classroom model. The coupled quality score is exploratory, not proof that a challenge is completed. ${esc(m.warnings.join(' · '))}</small></details>`}
function challengeScorePanel(){const s=dailySummary(challengeLedger,day+1,learningLevel);const names=challengeEnglish?.challenges||{};const defs=challengeManifest?.days?.[day]?.challenges as string[]|undefined;const ids=defs||Array.from({length:s.total},(_,i)=>'d'+(day+1)+'-'+(i+1));return `<details class="challenge-score-panel"><summary>🎯 Level ${learningLevel} challenges · ${s.validated}/${s.total} checks · ${s.stale} stale</summary><p>Live evidence from supported starter solvers. Unimplemented challenges cannot be completed. Upstream changes require revalidation.</p><div class="challenge-score-list">${ids.map(id=>{const e=challengeLedger.evidence[id+':'+learningLevel];const t=names[id];const best=challengeLedger.best[id+':'+learningLevel];return `<div class="challenge-score-row"><span>${e?.status==='validated'?'✓':e?.status==='failed'?'△':e?.status==='stale'?'↻':'○'}</span><button data-challenge="${id}" title="Read challenge details">${esc(t?.title||id)}</button><small>${e?.status||'not tested'}${e?.score!==null&&e?.score!==undefined?' · '+e.score+'/100':''}${best?' · best '+best.score:''}</small></div>`}).join('')}</div><div id="challenge-detail" aria-live="polite"></div></details>`}
function setupChallengePanel(){document.querySelectorAll<HTMLButtonElement>('[data-challenge]').forEach(b=>b.onclick=async()=>{const id=b.dataset.challenge!;const area=document.querySelector<HTMLElement>('#challenge-detail');if(!area)return;try{const [data,lang]=await Promise.all([loadChallenge(day+1,learningLevel,id),challengeEnglish?Promise.resolve(challengeEnglish):loadEnglish()]);challengeEnglish=lang;const words=lang.challenges[id];area.innerHTML=`<h3>${esc(words?.title||id)}</h3><p>${esc(words?.objective||'')}</p><p>${esc(words?.approach||'')}</p><p>${esc(words?.reflection||'')}</p><small>Parameter: ${esc(data.model.parameter)} · ${esc(data.model.unit)} · ${esc(data.implementation.validator)}</small>`}catch(err){area.textContent='Unable to load challenge: '+String(err)}})}
function challengePanel(index:number){const mission=creationChallenges[index];return `<details class="creation-mission" open><summary>☑ God's Mathematics — ${esc(mission.title)} · 0/${mission.items.length} validated</summary><p class="mission-note">Challenge roadmap: these tasks are not yet validated by the physics engine. Completing the existing graph exercise does not complete the day.</p><ol>${mission.items.map((item,i)=>`<li><span class="challenge-status">◇</span> <span>${esc(item.name)}</span> <button type="button" data-explain="${index}:${i}" aria-label="Explain ${esc(item.name)}">ⓘ</button> ${item.dependsOn.length?'<small>Requires previous challenge</small>':''}</li>`).join('')}</ol></details>`;}
function format(n:number){return Math.abs(n)>1e5?n.toExponential(3):n.toLocaleString(undefined,{maximumFractionDigits:3});}
function unit(d:number,v:number|undefined){return ['THz · visible light approximately 400–700 nm',v===0?'Ice':v===1?'Liquid water':'Steam','m/s²','km/s · circular two-body approximation','W/m²','organisms after 80 time steps'][d]||'';}
function isBuiltInNode(n:Node){return !n.id.startsWith('n')&&(day===0?newStarGraph().nodes:stages[day].nodes).some(original=>original.id===n.id)}
function tidyGraph(){const columns=day===0?[['mass','radius','hydrogen','coreMK','luminosity'],['gravity','pressure','core','fusion'],['hydro','thermal'],['stable'],['out']]:[nodes.filter(n=>n.kind==='number').map(n=>n.id),nodes.filter(n=>n.kind==='formula'||n.kind==='group').map(n=>n.id),nodes.filter(n=>n.kind==='output').map(n=>n.id)];const placed=new Set<string>();columns.forEach((ids,col)=>ids.forEach((id,row)=>{const n=nodes.find(x=>x.id===id);if(n){n.x=24+col*250;n.y=25+row*166;placed.add(id)}}));let row=0;nodes.filter(n=>!placed.has(n.id)).forEach(n=>{n.x=24+Math.max(0,columns.length-1)*250;n.y=25+row++*166});save();render()}
function pendingTargets(){if(!pending)return [];return day===0&&!parentGraph?guideSteps.flatMap(step=>step.inputs.map((input,slot)=>({to:step.id,slot,from:input.id}))).filter(item=>item.from===pending&&nodes.some(n=>n.id===item.to)):nodes.filter(n=>n.kind!=='number'&&n.kind!=='group-input').flatMap(n=>Array.from({length:n.kind==='output'?1:arity[n.op]??1},(_,slot)=>({to:n.id,slot,from:pending!}))).filter(item=>item.to!==pending)}
function connectSelected(to:string,slot:number){if(!pending||to===pending)return;const from=pending;if(day===0&&!parentGraph){const verdict=connectionFeedback(nodes,edges,from,to,slot);connectionNotice=verdict.message;if(verdict.ok){edges=edges.filter(e=>!(e.to===to&&e.slot===slot));edges.push({from,to,slot});save();guideIndex=nextGuideStep(edges);focusedChallenge=guideSteps[guideIndex]?.id||null}else{render();return}}else{const next=edges.filter(e=>!(e.to===to&&e.slot===slot)).concat({from,to,slot});const dim=checkDimensions(nodes,next);if(dim.errors.length){connectionNotice=dim.errors[0];alert(dim.errors[0]);render();return}edges=next;save()}pending=null;render()}
function nodeOutputPreview(id:string){const node=nodes.find(n=>n.id===id);if(!node)return {message:'Node unavailable',ready:false};const probe=evaluate(nodes,edges.filter(e=>e.to!=='out').concat({from:id,to:'out',slot:0}));const value=probe.values[id];return value!==undefined&&Number.isFinite(value)?{message:format(value)+(node.unit?' '+node.unit:''),ready:true}:{message:'Connect this node’s required inputs first. '+(probe.errors[0]||''),ready:false}}
function outputSelectionPanel(){if(!pending)return '';const targets=pendingTargets();return `<div class="connection-picker" role="region" aria-label="Connect output"><strong>Connect ${esc(nodes.find(n=>n.id===pending)?.label||pending)} to:</strong>${targets.length?targets.map(target=>`<button type="button" data-connect-to="${target.to}" data-connect-slot="${target.slot}">${esc(nodes.find(n=>n.id===target.to)?.label||target.to)} · input ${target.slot+1}</button>`).join(''):'<span>No required downstream connection for this output.</span>'}<button type="button" id="cancel-connection">Cancel</button></div>`}

function nodesView(){const calculated=evaluate(nodes,edges);const visible=focusIds();const shown=visible?nodes.filter(n=>visible.has(n.id)):nodes;const step=focusedChallenge?guideSteps.find(s=>s.id===focusedChallenge):null;return `${challengeWorkspace?'<div class="challenge-editor-nav"><button id="close-mission" type="button">← Save & return to challenges</button><strong>'+esc(missionItems()[selectedMissionChallenge]?.title||'Challenge')+'</strong></div>':''}<div class="node-tools">${day===0&&!parentGraph?`<div class="challenge-picker"><label for="focus-challenge">Maths challenge</label><select id="focus-challenge"><option value="all" ${!focusedChallenge?'selected':''}>Master graph · All nodes</option>${guideSteps.map((s,i)=>`<option value="${s.id}" ${focusedChallenge===s.id?'selected':''}>${i+1}. ${esc(s.title)}</option>`).join('')}</select><small>${step?esc(step.explanation):'Advanced: all interconnected equations'}</small></div>`:''}<select id="palette"><option value="">+ Add node…</option>${['constant','group','add','multiply','divide','sqrt',...Object.keys(arity).filter(x=>!['add','multiply','divide','sqrt'].includes(x))].map(x=>`<option value="${x}">${esc(x)}</option>`).join('')}</select><button id="tidy-graph" title="Arrange nodes without changing connections">▦ Tidy layout</button><details class="advanced-node-tools"><summary>More tools</summary><button id="auto">Auto-wire example</button><button id="clear">Clear wires</button></details>${parentGraph?'<button id="back-group">← Back to universe graph</button>':''}<span class="helper">${pending?'Selected '+esc(nodes.find(n=>n.id===pending)?.label||pending)+'. Choose a destination below.':'Tap OUT to inspect a result, or connect it to a highlighted input'}</span>${outputSelectionPanel()}</div><div class="graph-scroll"><div class="graph" id="graph"><svg id="wires"></svg>${shown.map((node,index)=>`<article class="node ${selected===node.id?'selected':''} ${day===0&&guideSteps[guideIndex]?.id===node.id?'guide-target':''}" data-node="${node.id}" style="left:${visible?(index%2===0?20:285):node.x}px;top:${visible?(Math.floor(index/2)*155+20):node.y}px"><div class="node-title" data-drag="${node.id}"><span>${node.kind==='number'?'▣':node.kind==='group-input'?'↪':node.kind==='group'?'▤':node.kind==='output'?'◈':'ƒ'}</span>${esc(node.label)}<button data-select="${node.id}" title="Explain and edit node" aria-label="Explain and edit ${esc(node.label)}">ⓘ</button></div><div class="ports">${node.kind!=='number'&&node.kind!=='group-input'?Array.from({length:node.kind==='output'?1:arity[node.op]??1},(_,i)=>`<button class="port in ${pending&&pendingTargets().some(t=>t.to===node.id&&t.slot===i)?'port-compatible':''} ${pending&&!pendingTargets().some(t=>t.to===node.id&&t.slot===i)?'port-incompatible':''}" data-in="${node.id}" data-slot="${i}" aria-label="Connect input ${i+1}${day===0?' expected '+(guideSteps.find(s=>s.id===node.id)?.inputs[i]?.unit||''):''}">● <small>${i===0?'A':'B'}</small></button>`).join(''):'<span class="port-label">Parameter</span>'}${node.kind!=='output'?`<button class="port out ${pending===node.id?'pending':''}" data-out="${node.id}" aria-label="Select output">OUT ●</button>`:''}</div>${node.kind==='formula'||node.kind==='group'?`<div class="node-reading" role="status">${calculated.values[node.id]===undefined?'◷ Connect inputs to calculate':'✓ Output: '+format(calculated.values[node.id])+(node.unit?' '+esc(node.unit):'')}</div>`:'' }<div class="node-meta">${node.kind==='number'?format(node.value||0)+(node.unit?' '+node.unit:''):node.kind==='group-input'?'Parent graph input':node.kind==='formula'||node.kind==='group'?esc(symbols[node.op]||node.op)+(node.unit?' · '+esc(node.unit):''):'Simulation'}</div></article>`).join('')}</div></div>`;}
function mathsView(values:Record<string,number>,errors:string[]){const dims=checkDimensions(nodes,edges);return `<div class="math-view"><h2>Live mathematics</h2><p>Connected formulas are evaluated in graph order. Missing connections stop downstream calculations.</p>${nodes.filter(n=>n.kind==='formula').map(n=>`<div class="math-card"><strong>${esc(n.label)}</strong><code>${esc(n.op==='expression'?(n.expression||'A+B'):(symbols[n.op]||n.op))}</code><div class="math-actions"><button data-math-jump="${n.id}">↗ Jump to node</button><button data-math-edit="${n.id}">✎ Edit equation</button></div><span>${values[n.id]===undefined?'Incomplete':format(values[n.id])} · ${esc(dims.units[n.id]||n.unit||'unit pending')}</span></div>`).join('')}<div class="errors">${[...errors,...dims.errors].length?[...errors,...dims.errors].map(e=>`<p>⚠ ${esc(e)}</p>`).join(''):'✓ Graph evaluates with compatible dimensions'}</div><small>Day 4 uses a three-body Newtonian integrator; energy drift is monitored. Long-term stability is not guaranteed. Other days retain simplified educational models.</small></div>`;}
function paramsView(){return `<div class="parameters"><h2>Input parameters</h2><p>Adjust these values to change the live output. Connect them on the Nodes tab.</p>${nodes.filter(n=>n.kind==='number').map(n=>`<label class="parameter"><span>${esc(n.label)} <small>${esc(n.unit||'')}</small></span><input type="number" data-param="${n.id}" value="${n.value??1}" step="any" inputmode="decimal" /></label>`).join('')}<button id="import">Import saved JSON</button><input id="import-file" type="file" accept="application/json" hidden /></div>`;}
function wireUI(){const graph=document.querySelector<HTMLElement>('#graph')!;
 document.querySelectorAll<HTMLButtonElement>('[data-mission-index]').forEach(b=>b.onclick=()=>openMission(Number(b.dataset.missionIndex)));
 document.querySelector<HTMLButtonElement>('#close-mission')?.addEventListener('click',()=>closeMission());
 document.querySelector<HTMLSelectElement>('#focus-challenge')?.addEventListener('change',e=>focusChallenge((e.target as HTMLSelectElement).value==='all'?null:(e.target as HTMLSelectElement).value));
 document.querySelector<HTMLSelectElement>('#palette')!.onchange=e=>{const op=(e.target as HTMLSelectElement).value;if(op)addNode(op)};
 document.querySelector<HTMLButtonElement>('#tidy-graph')?.addEventListener('click',tidyGraph);
 document.querySelector<HTMLButtonElement>('#clear')!.onclick=()=>{edges=[];if(day===0){guideIndex=0;connectionNotice='All connections cleared. Start with gravity.'}save();render()};
 document.querySelector<HTMLButtonElement>('#auto')!.onclick=()=>{if(day===0){alert('Day 1 requires you to connect the equations yourself. Use the wiring guide in the challenge panel.');return;}const inputs=nodes.filter(n=>n.kind==='number'||n.kind==='group-input'),calc=nodes.find(n=>n.kind==='formula'||n.kind==='group'),out=nodes.find(n=>n.kind==='output');if(calc&&out){edges=inputs.slice(0,arity[calc.op]||1).map((n,i)=>({from:n.id,to:calc.id,slot:i}));edges.push({from:calc.id,to:out.id,slot:0});save();render()}};
 graph.querySelectorAll<HTMLButtonElement>('[data-out]').forEach(b=>b.onclick=()=>{pending=b.dataset.out!;connectionNotice='Selected '+(nodes.find(n=>n.id===pending)?.label||pending)+'. Choose a compatible input socket.';render()});
 graph.querySelectorAll<HTMLButtonElement>('[data-in]').forEach(b=>b.onclick=()=>connectSelected(b.dataset.in!,Number(b.dataset.slot)));
 document.querySelectorAll<HTMLButtonElement>('[data-connect-to]').forEach(b=>b.onclick=()=>connectSelected(b.dataset.connectTo!,Number(b.dataset.connectSlot)));
 document.querySelector<HTMLButtonElement>('#cancel-connection')?.addEventListener('click',()=>{pending=null;render()});
 graph.querySelectorAll<HTMLButtonElement>('[data-select]').forEach(b=>b.onclick=e=>{e.stopPropagation();selected=b.dataset.select!;inspectorHelp=true;inspectorTab='learn';inspectorOpen=true;subgraph=false;render()});
 graph.querySelectorAll<HTMLElement>('[data-node]').forEach(el=>el.addEventListener('click',e=>{if((e.target as HTMLElement).closest('button,input,[data-in],[data-out]'))return;selected=el.dataset.node!;inspectorHelp=true;inspectorTab='learn';inspectorOpen=true;render()}));
 document.querySelector<HTMLButtonElement>('#node-help')?.addEventListener('click',()=>{inspectorHelp=!inspectorHelp;render()});
 document.querySelector<HTMLFormElement>('#equation-editor')?.addEventListener('submit',e=>{e.preventDefault();const n=nodes.find(n=>n.id===selected);if(!n)return;const field=document.querySelector<HTMLInputElement>('#equation-input')!;const expression=field.value.trim();try{evaluateExpression(expression,2,3);n.op='expression';n.expression=expression;n.label='Custom: '+expression;n.unit='dimensionless';save();render()}catch(err){alert('Equation error: '+String(err))}});
 document.querySelector<HTMLButtonElement>('#equation-reset')?.addEventListener('click',()=>{const n=nodes.find(n=>n.id===selected);if(!n)return;const original=stages[day].nodes.find(x=>x.id===n.id);if(original){n.op=original.op;n.expression=undefined;n.label=original.label;n.unit=original.unit;save();render()}});
 document.querySelector<HTMLInputElement>('#node-value')?.addEventListener('change',e=>{const n=nodes.find(n=>n.id===selected);const v=Number((e.target as HTMLInputElement).value);if(n&&Number.isFinite(v)){n.value=v;save();render()}});
 const open=document.querySelector<HTMLButtonElement>('#open-group');if(open)open.onclick=()=>{const n=nodes.find(n=>n.id===selected);if(n?.kind==='group'&&n.group){parentGraph={nodes,edges,groupId:n.id};nodes=clone(n.group.nodes);edges=clone(n.group.edges);selected=null;pending=null;graphScrollX=graphScrollY=0;render();}else{subgraph=!subgraph;render()}};const back=document.querySelector<HTMLButtonElement>('#back-group');if(back)back.onclick=()=>{save();nodes=parentGraph!.nodes;edges=parentGraph!.edges;parentGraph=null;selected=null;graphScrollX=graphScrollY=0;render()};
 const del=document.querySelector<HTMLButtonElement>('#delete-node');if(del)del.onclick=()=>{nodes=nodes.filter(n=>n.id!==selected);edges=edges.filter(e=>e.from!==selected&&e.to!==selected);selected=null;save();render()};
 graph.querySelectorAll<HTMLElement>('[data-drag]').forEach(handle=>{handle.onpointerdown=e=>{if((e.target as HTMLElement).closest('button'))return;const node=nodes.find(n=>n.id===handle.dataset.drag)!;const x=e.clientX,y=e.clientY,sx=node.x,sy=node.y;handle.setPointerCapture(e.pointerId);handle.onpointermove=m=>{node.x=Math.max(0,sx+(m.clientX-x)/zoom);node.y=Math.max(0,sy+(m.clientY-y)/zoom);(handle.parentElement as HTMLElement).style.left=node.x+'px';(handle.parentElement as HTMLElement).style.top=node.y+'px';drawWires()};handle.onpointerup=()=>{handle.onpointermove=null;save()}}});
}
function parameterUI(){document.querySelectorAll<HTMLInputElement>('[data-param]').forEach(input=>input.onchange=()=>{const n=nodes.find(n=>n.id===input.dataset.param);if(n){n.value=Number(input.value);save();render()}});document.querySelector<HTMLButtonElement>('#import')!.onclick=()=>document.querySelector<HTMLInputElement>('#import-file')!.click();document.querySelector<HTMLInputElement>('#import-file')!.onchange=async e=>{const f=(e.target as HTMLInputElement).files?.[0];if(!f)return;try{const data=JSON.parse(await f.text());if(!Array.isArray(data.nodes)||!Array.isArray(data.edges))throw Error('Invalid graph');nodes=data.nodes;edges=data.edges;save();render()}catch{alert('Could not import graph JSON')}}}
function mathUI(){document.querySelectorAll<HTMLButtonElement>('[data-math-jump]').forEach(b=>b.onclick=()=>{selected=b.dataset.mathJump!;inspectorHelp=true;tab='nodes';render();document.querySelector<HTMLElement>('[data-node="'+selected+'"]')?.scrollIntoView({block:'nearest',inline:'nearest'})});document.querySelectorAll<HTMLButtonElement>('[data-math-edit]').forEach(b=>b.onclick=()=>{const id=b.dataset.mathEdit!;const n=nodes.find(n=>n.id===id);if(!n)return;selected=id;inspectorHelp=true;tab='nodes';render();document.querySelector<HTMLElement>('#equation-editor')?.scrollIntoView({block:'nearest'})})}
function defaultGroup(){return {nodes:[{id:'a',kind:'group-input' as const,op:'input0',label:'Input A',x:20,y:45},{id:'b',kind:'group-input' as const,op:'input1',label:'Input B',x:20,y:185},{id:'sum',kind:'formula' as const,op:'add',label:'A + B',x:295,y:95},{id:'out',kind:'output' as const,op:'display',label:'Group output',x:580,y:110}],edges:[{from:'a',to:'sum',slot:0},{from:'b',to:'sum',slot:1},{from:'sum',to:'out',slot:0}]};}
function drawWires(){const svg=document.querySelector<SVGSVGElement>('#wires');if(!svg)return;const graph=document.querySelector<HTMLElement>('#graph')!;const gr=graph.getBoundingClientRect();svg.innerHTML='';for(const edge of edges){const a=graph.querySelector<HTMLElement>(`[data-out="${edge.from}"]`),b=graph.querySelector<HTMLElement>(`[data-in="${edge.to}"][data-slot="${edge.slot}"]`);if(!a||!b)continue;const ar=a.getBoundingClientRect(),br=b.getBoundingClientRect(),x1=ar.right-gr.left,y1=ar.top+ar.height/2-gr.top,x2=br.left-gr.left,y2=br.top+br.height/2-gr.top;svg.innerHTML+=`<path d="M${x1},${y1} C${x1+65},${y1} ${x2-65},${y2} ${x2},${y2}" stroke="#67c6ff" stroke-width="3" fill="none"/>`}}
function drawUniverse(){if(world3d){const g=day===0?checkStarGraph(masterWorkspace?.nodes||parentGraph?.nodes||nodes,masterWorkspace?.edges||parentGraph?.edges||edges):null;world3d.update(day,t,g?.input?.radius??1,g?.input?.coreMK??15.7,g?.complete??false);return}const c=document.querySelector<HTMLCanvasElement>('#sky');if(!c)return;const rect=c.getBoundingClientRect();const ratio=Math.min(devicePixelRatio||1,2);c.width=Math.max(1,rect.width*ratio);c.height=Math.max(1,rect.height*ratio);const ctx=c.getContext('2d')!;ctx.scale(ratio,ratio);const w=rect.width,h=rect.height,cx=w/2,cy=h/2;const ev=evaluate(parentGraph?parentGraph.nodes:nodes,parentGraph?parentGraph.edges:edges),valid=ev.result!==undefined;ctx.clearRect(0,0,w,h);ctx.fillStyle='#050c1c';ctx.fillRect(0,0,w,h);for(let i=0;i<85;i++){const x=(i*113.7)%w,y=(i*71.9)%h;ctx.fillStyle=`rgba(210,229,255,${.18+(i%5)*.1})`;ctx.fillRect(x,y,1.3,1.3)}if(!valid){ctx.fillStyle='#91a4c8';ctx.textAlign='center';ctx.font='15px system-ui';ctx.fillText('Complete the graph to create your world',cx,cy);return;}const v=ev.result!;
 const circle=(x:number,y:number,r:number,color:string)=>{ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fillStyle=color;ctx.fill()};
 if(day===0){const hue=Math.max(0,Math.min(280,(750-(nodes[0]?.value||550))*0.78));const g=ctx.createRadialGradient(cx,cy,3,cx,cy,Math.min(w,h)*.35);g.addColorStop(0,`hsla(${hue},100%,80%,1)`);g.addColorStop(.3,`hsla(${hue},95%,52%,.8)`);g.addColorStop(1,'transparent');ctx.fillStyle=g;ctx.fillRect(0,0,w,h)}
 if(day===1){circle(cx,cy,Math.min(w,h)*.27,v===0?'#b9e8ff':v===1?'#388de0':'#a3a5d1');}
 if(day===2){circle(cx,cy,Math.min(w,h)*.25,'#3c80ca');circle(cx-25,cy+12,Math.min(w,h)*.07,'#5ac897');ctx.fillStyle='#fff';ctx.textAlign='center';ctx.fillText(`${v.toFixed(2)} m/s²`,cx,cy+5)}
 if(day===3){
  const sun=orbital.bodies[0],earth=orbital.bodies.find(b=>b.name==='Earth')!;
  const maxAU=orbitScale==='inner'?2:33;
  const scale=Math.min(w*.43,h*.40)/maxAU;
  const pos=(b:Body)=>({x:cx+(b.x-sun.x)*scale,y:cy+(b.y-sun.y)*scale});
  for(const p of orbital.config){const r=p.radiusAU*scale;ctx.beginPath();ctx.arc(cx,cy,r,0,2*Math.PI);ctx.strokeStyle='#39506b66';ctx.stroke();}
  for(const b of orbital.bodies){if(b.name==='Moon')continue;
   const trail=orbital.trails[b.name]||[];ctx.beginPath();trail.forEach((pt,i)=>{const x=cx+(pt.x-sun.x)*scale,y=cy+(pt.y-sun.y)*scale;i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.strokeStyle=b.color+'99';ctx.stroke();
   const q=pos(b);circle(q.x,q.y,b.name==='Sun'?10:orbitScale==='inner'?Math.max(3,b.radius):Math.max(2,b.radius*.7),b.color);
   if(b.name===orbitFocus){ctx.strokeStyle='#fff';ctx.beginPath();ctx.arc(q.x,q.y,12,0,2*Math.PI);ctx.stroke();ctx.fillStyle='#e5f3ff';ctx.textAlign='left';ctx.font='11px system-ui';ctx.fillText(b.name,q.x+14,q.y-9);}
  }
  if(orbitScale==='inner'){const moon=orbital.bodies.find(b=>b.name==='Moon');if(moon){const ep=pos(earth),dx=(moon.x-earth.x)/.00257,dy=(moon.y-earth.y)/.00257;circle(ep.x+dx*14,ep.y+dy*14,3,'#d8dce5');}}
  ctx.fillStyle='#c7d8ef';ctx.textAlign='left';ctx.font='11px system-ui';ctx.fillText(`${orbital.bodies.length} bodies · ${orbital.years.toFixed(2)} years · ΔE ${(orbital.maxEnergyDrift*100).toFixed(4)}%`,12,h-10);
 }
 if(day===4){const r=Math.min(w*.27,h*.37);circle(cx,cy,22,'#ffc35a');ctx.strokeStyle='#4c6589';ctx.beginPath();ctx.ellipse(cx,cy,r,r*.46,0,0,Math.PI*2);ctx.stroke();const a=t*.012;circle(cx+r*Math.cos(a),cy+r*.46*Math.sin(a),9,'#5daaf7');}
 if(day===5){const r=Math.min(w,h)*.25;circle(cx,cy,r,'#247a70');for(let i=0;i<Math.min(70,Math.max(0,v/15));i++){const a=i*2.399+t*.002;circle(cx+Math.cos(a)*r*.83*Math.sqrt(i/70),cy+Math.sin(a)*r*.83*Math.sqrt(i/70),2.4,'#c5f08b')}}
}
function orbitsView(){return `<div class="orbit-lab"><div class="orbit-toolbar"><h2>Solar system laboratory</h2><button id="orbit-reset">Restore solar system</button><button id="orbit-restart">↺ Restart experiment</button></div><p>All eight planets interact through Newtonian gravity. Edit one orbit at a time and watch the simulation. The Moon is included with Earth.</p><div class="orbit-toolbar"><label>View <select id="orbit-scale"><option value="outer" ${orbitScale==='outer'?'selected':''}>All planets</option><option value="inner" ${orbitScale==='inner'?'selected':''}>Inner planets</option></select></label><label>Simulation speed <select id="orbit-speed">${[1,2,4,8].map(n=>`<option value="${n}" ${orbital.speed===n?'selected':''}>${n}×</option>`).join('')}</select></label><label><input type="checkbox" id="orbit-moon" ${orbital.moon?'checked':''}/> Include Moon</label></div><div class="orbit-toolbar"><label>Star mass (solar masses) <input id="orbit-star" type="number" min="0.05" max="5" step="0.05" value="${orbital.starMass}"/></label><label>Planet <select id="orbit-focus">${orbital.config.map(p=>`<option value="${p.name}" ${orbitFocus===p.name?'selected':''}>${p.name}</option>`).join('')}</select></label></div><div class="orbit-params">${orbital.config.filter(p=>p.name===orbitFocus).map(p=>[['mass','Mass (solar masses)',p.mass],['radiusAU','Distance (AU)',p.radiusAU],['phaseDeg','Starting angle (°)',p.phaseDeg],['speedFactor','Velocity multiplier',p.speedFactor]].map(([key,label,value])=>`<label class="parameter"><span>${label}</span><input type="number" data-orbit-param="${key}" value="${value}" step="any" inputmode="decimal" /></label>`).join('')).join('')}</div><h3>Stability challenges</h3><div id="challenge-list">${challenges.map(c=>{const status=orbital.status(c);return `<article class="challenge"><strong>${c.title}</strong><p>${c.description}</p><span class="challenge-status ${status}">${status==='passed'?'✓ Passed':status==='failed'?'✕ Failed — restart or adjust parameters':`◷ Testing · ${Math.min(100,orbital.years/c.duration*100).toFixed(0)}%`}${orbital.best[c.id]?' · 🏆 Earned':''}</span></article>`}).join('')}</div><p class="orbit-note">Challenge checks use maximum radial departure from the starting orbit and numerical energy drift. These are simplified classroom tests, not proof of billion-year stability. Planet positions are approximate and coplanar; no relativistic effects.</p></div>`}
function orbitsUI(){const $=<T extends HTMLElement>(id:string)=>document.querySelector<T>(id)!;
 $('#orbit-reset').addEventListener('click',()=>{orbital.restore();orbitFocus='Earth';render()});
 $('#orbit-restart').addEventListener('click',()=>{orbital.reset();render()});
 $('#orbit-scale').addEventListener('change',e=>{orbitScale=(e.target as HTMLSelectElement).value as typeof orbitScale;render()});
 $('#orbit-speed').addEventListener('change',e=>{orbital.speed=Number((e.target as HTMLSelectElement).value);render()});
 $('#orbit-moon').addEventListener('change',e=>{orbital.moon=(e.target as HTMLInputElement).checked;orbital.reset();render()});
 $('#orbit-focus').addEventListener('change',e=>{orbitFocus=(e.target as HTMLSelectElement).value;render()});
 $('#orbit-star').addEventListener('change',e=>{orbital.starMass=Math.max(.05,Math.min(5,Number((e.target as HTMLInputElement).value)||1));orbital.reset();render()});
 document.querySelectorAll<HTMLInputElement>('[data-orbit-param]').forEach(el=>el.onchange=()=>{orbital.update(orbitFocus,el.dataset.orbitParam as 'mass'|'radiusAU'|'phaseDeg'|'speedFactor',Number(el.value));render()});
}
app.innerHTML='<div class="boot-screen" role="status"><div class="boot-spinner"></div><p>Preparing Creation Studio…</p></div>';registerPwa();restoreWorld().finally(()=>{observeUser(u=>{user=u;if(!hasStarted)landing();else render()});finishRedirect().catch(e=>console.warn('Sign-in redirect',e));landing()});let last=0;function tick(now:number){if(now-last>40){if(playing){t+=1;if(day===3 && evaluate(parentGraph?parentGraph.nodes:nodes,parentGraph?parentGraph.edges:edges).result!==undefined){orbital.step();const list=document.querySelector<HTMLElement>('#challenge-list');if(list){list.innerHTML=challenges.map(c=>{const status=orbital.status(c);return `<article class="challenge"><strong>${c.title}</strong><p>${c.description}</p><span class="challenge-status ${status}">${status==='passed'?'✓ Passed':status==='failed'?'✕ Failed — restart or adjust parameters':`◷ Testing · ${Math.min(100,orbital.years/c.duration*100).toFixed(0)}%`}${orbital.best[c.id]?' · 🏆 Earned':''}</span></article>`}).join('');}}}drawUniverse();last=now}requestAnimationFrame(tick)}requestAnimationFrame(tick);
